"use strict";(self.webpackChunkpf_1_ee=self.webpackChunkpf_1_ee||[]).push([[5080],{1738:(e,n,a)=>{a.r(n),a.d(n,{assets:()=>l,contentTitle:()=>o,default:()=>d,frontMatter:()=>r,metadata:()=>t,toc:()=>h});const t=JSON.parse('{"id":"srd/races/versatile-lineages/changelings","title":"Changelings","description":"Changelings are the eerie offspring of mortal unions with hags\u2014be they born of deception, dark magic, or madness. Whether conceived through occult rituals or monstrous seduction, changelings are rarely raised by their true mothers. Instead, they are left in the care of strangers: placed on stoops, found swaddled in the woods, or even discovered at the center of half-finished witch circles.","source":"@site/docs/srd/races/versatile-lineages/changelings.md","sourceDirName":"srd/races/versatile-lineages","slug":"/srd/races/versatile-lineages/changelings","permalink":"/PF1EE/docs/srd/races/versatile-lineages/changelings","draft":false,"unlisted":false,"editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/docs/srd/races/versatile-lineages/changelings.md","tags":[],"version":"current","frontMatter":{},"sidebar":"srdSidebar","previous":{"title":"Aasimars","permalink":"/PF1EE/docs/srd/races/versatile-lineages/aasimars"},"next":{"title":"Dhampirs","permalink":"/PF1EE/docs/srd/races/versatile-lineages/dhampirs"}}');var s=a(4848),i=a(8453);const r={},o="Changelings",l={},h=[{value:"Changeling Details",id:"changeling-details",level:2},{value:"Hagborn",id:"hagborn",level:3}];function c(e){const n={h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",ul:"ul",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"changelings",children:"Changelings"})}),"\n",(0,s.jsx)(n.p,{children:"Changelings are the eerie offspring of mortal unions with hags\u2014be they born of deception, dark magic, or madness. Whether conceived through occult rituals or monstrous seduction, changelings are rarely raised by their true mothers. Instead, they are left in the care of strangers: placed on stoops, found swaddled in the woods, or even discovered at the center of half-finished witch circles."}),"\n",(0,s.jsx)(n.p,{children:"Despite often resembling their mortal parent\u2019s ancestry, changelings bear unmistakable marks of their lineage. Most are tall and lithe, with unnaturally pale skin and mismatched eyes\u2014one echoing their mortal lineage, the other reflecting the baleful hue of their hag mother. These unusual traits, especially their mismatched gaze, often incite suspicion or superstition, branding them as cursed or fey-touched. Such children may grow up as outcasts, fostered with wariness or driven from their communities entirely."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"The Call:"})," At some point during adolescence or early adulthood, changelings experience the Call\u2014a haunting whisper in their soul that urges them to seek their origins. This psychic pull is often described as a voice heard only in dreams, a compulsion tied not to memory but to fate. It leads them toward strange places, occult secrets, or even directly into the territory of the hag who birthed them."]}),"\n",(0,s.jsx)(n.p,{children:"Those who resist the Call forge their own path, often becoming witch-hunters, scholars of forbidden lore, or champions of mortals threatened by the supernatural. But those who embrace it may eventually join a coven, succumbing to their transformation into full-fledged hags over time\u2014a fate both feared and coveted, depending on the changeling\u2019s nature."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Occult Legacy:"})," The blood of hags carries ancient, twisted power. Even changelings who avoid dark destinies often manifest fragments of that legacy: sharpened claws, unnatural resilience, or an instinctive grasp of magic. These abilities are typically subtle in childhood, but grow more pronounced as they age\u2014especially for those who dwell near ley lines, fey woods, or places of deep mystery."]}),"\n",(0,s.jsx)(n.p,{children:"Not all changelings are alike. Their nature is shaped not only by their father\u2019s ancestry, but also by the type of hag who bore them\u2014green hags breed cunning and trickery, night hags pass on dreams and death, and sea hags bestow eerie beauty and tempests of emotion. Entire covens sometimes craft changelings deliberately, using them as agents in the mortal world or as candidates for future membership."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Society and Isolation:"})," While changelings can be of any gender, tales and traditions often focus on women due to the greater frequency with which the Call affects them. Some changelings hide their nature, seeking normal lives under false names. Others lean into the fear they inspire, carving out reputations as seers, witches, or guardians of haunted places."]}),"\n",(0,s.jsx)(n.p,{children:"Whatever their path, changelings straddle the line between the mortal world and the monstrous, forever caught between the blood that calls to them and the will that defines them."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"changeling-details",children:"Changeling Details"}),"\n",(0,s.jsx)(n.p,{children:"To play a character with a Changeling lineage, first select your race, just like you would for any character. You gain hit points, type, size, speed, languages, lineage traits, and other abilities from that race. Then, instead of choosing a lineage from those normally available to that race, apply your chosen Changeling lineage. You gain all the features from your Changeling lineage, some of which might modify or replace statistics, abilities, or traits from your race."}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"When you apply a Changeling lineage, you gain the Changeling subtype,"})," while retaining any racial subtypes, creature size, and racial traits associated with your base race (e.g., Dwarf, Elf, Human)."]}),"\n",(0,s.jsx)(n.p,{children:"Since a Changeling lineage is a lineage, you can only apply one, and you cannot take another lineage in addition to your Changeling lineage."}),"\n",(0,s.jsx)(n.p,{children:"When selecting lineage traits, you can choose from those available to your race as well as those available to your Changeling lineage."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h3,{id:"hagborn",children:"Hagborn"}),"\n",(0,s.jsx)(n.p,{children:"Marked by eerie insight and an unsettling presence, Hagborn Changelings bear the legacy of their monstrous mothers. Their blood hums with foul magic and whispers secrets in the dark. Hagborn gain the following lineage Traits:"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Hag-Touched:"})," Born of a mortal and a hag, the Hagborn inherit unnatural insight and a strange charm, but their monstrous blood weakens their vitality. They gain +2 Wisdom, +2 Charisma, \u20132 Constitution, and a +2 bonus to one other ability score of their choice, except Wisdom or Charisma."]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Claws:"})," As a free action, a Hagborn can cause her nails to lengthen into jagged, talon-like claws. These claws are considered primary natural attacks and can be used to make two claw attacks (dealing 1d4 damage if Medium, or 1d3 if Small)."]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Haghide:"})," Changelings gain a +1 natural armor bonus due to their unnaturally tough flesh and resilient, hag-tainted skin."]}),"\n"]}),"\n",(0,s.jsxs)(n.li,{children:["\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"Witchborn Eyes:"})," Changelings can see twice as far as humans in conditions of dim light, gaining low-light vision. If they already have low-light vision from their base race, they instead gain darkvision out to 60 feet."]}),"\n"]}),"\n"]})]})}function d(e={}){const{wrapper:n}={...(0,i.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453:(e,n,a)=>{a.d(n,{R:()=>r,x:()=>o});var t=a(6540);const s={},i=t.createContext(s);function r(e){const n=t.useContext(i);return t.useMemo((function(){return"function"==typeof e?e(n):{...n,...e}}),[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),t.createElement(i.Provider,{value:n},e.children)}}}]);